set search_path = '';
select jsonb_build_object(
 'schemas',(select coalesce(jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl) order by nspname),'[]') from pg_namespace where nspname in ('public','private')),
 'types',(select coalesce(jsonb_agg(jsonb_build_object('identity',format_type(t.oid,null),'kind',t.typtype,'category',t.typcategory,'owner',pg_get_userbyid(t.typowner),'acl',t.typacl,'base',format_type(t.typbasetype,null),'element',format_type(t.typelem,null),'notNull',t.typnotnull,'default',t.typdefault,'labels',(select jsonb_agg(enumlabel order by enumsortorder) from pg_enum where enumtypid=t.oid)) order by n.nspname,t.typname),'[]') from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','private')),
 'relations',(select coalesce(jsonb_agg(jsonb_build_object('identity',format('%I.%I',n.nspname,c.relname),'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'replicaIdentity',c.relreplident,'options',c.reloptions,'persistence',c.relpersistence,'partition',c.relispartition) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind in ('r','p','v','m','S','f')),
 'columns',(select coalesce(jsonb_agg(jsonb_build_object('relation',format('%I.%I',n.nspname,c.relname),'number',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'collation',(select format('%I.%I',cn.nspname,co.collname) from pg_collation co join pg_namespace cn on cn.oid=co.collnamespace where co.oid=a.attcollation),'acl',a.attacl,'storage',a.attstorage,'options',a.attoptions,'statistics',a.attstattarget) order by n.nspname,c.relname,a.attnum),'[]') from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname in ('public','private') and c.relkind in ('r','p','v','m','S','f') and a.attnum>0 and not a.attisdropped),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('relation',case when conrelid=0 then null else conrelid::regclass::text end,'domain',case when contypid=0 then null else format_type(contypid,null) end,'name',conname,'definition',pg_get_constraintdef(oid,false),'validated',convalidated,'deferrable',condeferrable,'deferred',condeferred) order by conrelid::regclass::text,conname),'[]') from pg_constraint where connamespace in (select oid from pg_namespace where nspname in ('public','private'))),
 'indexes',(select coalesce(jsonb_agg(jsonb_build_object('identity',format('%I.%I',n.nspname,c.relname),'definition',pg_get_indexdef(c.oid),'valid',i.indisvalid,'ready',i.indisready,'clustered',i.indisclustered,'replicaIdentity',i.indisreplident) order by n.nspname,c.relname),'[]') from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')),
 'routines',(select coalesce(jsonb_agg(jsonb_build_object('identity',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'kind',p.prokind,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'language',l.lanname,'securityDefiner',p.prosecdef,'leakproof',p.proleakproof,'strict',p.proisstrict,'volatility',p.provolatile,'parallel',p.proparallel,'cost',p.procost,'rows',p.prorows,'config',p.proconfig) order by p.oid::regprocedure::text),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('public','private') and p.prokind in ('f','p')),
 'views',(select coalesce(jsonb_agg(jsonb_build_object('identity',format('%I.%I',n.nspname,c.relname),'definition',pg_get_viewdef(c.oid,false)) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind in ('v','m')),
 'policies',(select coalesce(jsonb_agg(jsonb_build_object('relation',format('%I.%I',n.nspname,c.relname),'name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(select jsonb_agg(case when roleid=0 then 'public' else pg_get_userbyid(roleid) end order by case when roleid=0 then 'public' else pg_get_userbyid(roleid) end) from unnest(p.polroles) roleid),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by n.nspname,c.relname,p.polname),'[]') from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')),
 'triggers',(select coalesce(jsonb_agg(jsonb_build_object('relation',format('%I.%I',n.nspname,c.relname),'name',t.tgname,'definition',pg_get_triggerdef(t.oid,false),'enabled',t.tgenabled) order by n.nspname,c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and not t.tgisinternal),
 'defaultACL',(select coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'kind',d.defaclobjtype,'acl',d.defaclacl) order by pg_get_userbyid(d.defaclrole),n.nspname,d.defaclobjtype),'[]') from pg_default_acl d join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in ('public','private'))
);
